    wires=[]
    for sec in sections:
        plane=cq.Plane(origin=(origin[0]+normal[0]*sec["z"],origin[1]+normal[1]*sec["z"],origin[2]+normal[2]*sec["z"]),xDir=xdir,normal=normal)
        wires.append(cq.Workplane(plane).polyline(sec["points"]).close().val())
